"""Independent descriptive M1/M2/M3: identical covered cohort, held spatial blocks.
Profiles measured2021 are not ex ante causes or a genuine demographic forecast.
"""
from pathlib import Path
import argparse,time,hashlib,json
import pandas as pd,numpy as np
from independent_core import equal_area6933

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,default=Path(__file__).resolve().parent.parent);ap.add_argument('--wait-seconds',type=int,default=300);ap.add_argument('--bootstrap-reps',type=int,default=399);a=ap.parse_args();r=a.root.resolve();o=r/'statistics';deadline=time.time()+a.wait_seconds
 while not ((r/'rfsd/primary2010/FINISHED.json').exists() and (r/'agriculture/zone_functional_main.csv').exists()):
  if time.time()>deadline:raise RuntimeError('Functional inputs not ready; no model result claimed')
  time.sleep(2)
 geo=pd.read_parquet(o/'independent_zone_covariates.parquet');crop=pd.read_csv(r/'agriculture/zone_functional_main.csv');fin=pd.read_parquet(r/'rfsd/primary2010/financial_observations.parquet');sector=pd.read_parquet(r/'rfsd/primary2010/sector_sensitivity.parquet');key=['year','center_id','max_distance_km','quality'];audit=[]
 def ck(name,condition,details=None):audit.append({'test':name,'passed':bool(condition),'details':details});assert condition,(name,details)
 ck('unique_financial_keys',not fin.duplicated(key).any());ck('unique_sector_keys',not sector.duplicated(key+['okved_section']).any());ck('unique_crop_and_geography_keys',crop.center_id.is_unique and geo.center_id.is_unique)
 sc=sector.groupby(key).n_organizations.sum();fc=fin.set_index(key).n_organizations;compare=pd.concat([sc.rename('sector'),fc.rename('financial')],axis=1).fillna(0);ck('all_six_RFSD_modes_count_exact',compare.sector.eq(compare.financial).all(),{'year_zone_mode_pairs':len(compare),'max_difference':float((compare.sector-compare.financial).abs().max())})
 ck('nonnegative_sector_counts',sector.n_organizations.ge(0).all());ss=sector[sector.year.eq(2021)&sector.quality.eq('baseline')&sector.max_distance_km.eq(5)].copy();ss['okved_section']=ss.okved_section.fillna('UNKNOWN');matrix=ss.groupby(['center_id','okved_section']).n_organizations.sum().unstack(fill_value=0);n=matrix.sum(axis=1);shares=matrix.div(n.replace(0,np.nan),axis=0);ck('sector_shares_sum_one',np.allclose(shares.sum(axis=1),1,rtol=0,atol=1e-12));eco=shares.add_prefix('sector_share_');eco['observed_organizations']=n;eco['log_observed_organizations']=np.log1p(n);eco['sector_diversity_entropy']=-(shares*np.log(shares.replace(0,np.nan))).sum(axis=1)
 f=geo.merge(crop,on='center_id',how='left',validate='one_to_one',suffixes=('','_agri')).merge(eco,on='center_id',how='left',validate='one_to_one');f=f[f.coverage.ge(.8)&f.observed_organizations.ge(5)&f.center_id.ne('UNASSIGNED')].copy();ck('functional_cohort_unique',f.center_id.is_unique);f['x'],f['y']=equal_area6933(f.lon.to_numpy(),f.lat.to_numpy());f=f[np.isfinite(f.x)&np.isfinite(f.y)].copy()
 basic=['log_mass2010','log_density25','log_distance','log_population2010','has_environment'];cropcols=[c for c in crop.columns if c.startswith('share_')];sectorcols=[c for c in eco if c.startswith('sector_share_')];models={'M1':basic,'M2':basic+cropcols+['coverage'],'M3':basic+cropcols+['coverage']+sectorcols+['log_observed_organizations','sector_diversity_entropy']};results=[];predictions=[];rng=np.random.default_rng(20261019)
 for ycol in ['outcome_total','outcome_environment']:
  cohort=f.copy() if ycol=='outcome_total' else f[f.noncenter_members.gt(0)].copy();y=cohort[ycol].to_numpy();ck('finite_outcome_'+ycol,np.isfinite(y).all())
  for size in [250,400,600]:
   d=cohort.copy();d['block_id']=np.floor(d.x/(size*1000)).astype(int).astype(str)+':'+np.floor(d.y/(size*1000)).astype(int).astype(str);d['fold']=d.block_id.map(lambda z:int(hashlib.sha256((f'sgrt-recovered2010:{size}:'+z).encode()).hexdigest()[:8],16)%5);by_model={}
   if len(d)<30 or d.block_id.nunique()<10:raise RuntimeError('Insufficient covered cohort for predeclared spatial validation')
   for model,cols in models.items():
    x=d[cols].to_numpy(float);pred=np.full(len(d),np.nan);foldinfo=[]
    for fold in range(5):
     te=d.fold.eq(fold).to_numpy();tr=~te
     if te.sum()==0 or tr.sum()<=len(cols)+2:raise RuntimeError('Predeclared fold too small; no outcome-adaptive fold change allowed')
     train=x[tr].copy();test=x[te].copy();med=np.zeros(x.shape[1]);
     for j in range(x.shape[1]):
      good=np.isfinite(train[:,j]);med[j]=np.median(train[good,j]) if good.any() else 0
     for j in range(x.shape[1]):train[~np.isfinite(train[:,j]),j]=med[j];test[~np.isfinite(test[:,j]),j]=med[j]
     mu=train.mean(0);sd=train.std(0);sd[sd==0]=1;train=np.c_[np.ones(tr.sum()),(train-mu)/sd];test=np.c_[np.ones(te.sum()),(test-mu)/sd];penalty=np.eye(train.shape[1]);penalty[0,0]=0;beta=np.linalg.pinv(train.T@train+penalty)@train.T@y[tr];pred[te]=test@beta;foldinfo.append({'fold':fold,'train_n':int(tr.sum()),'test_n':int(te.sum()),'train_blocks':int(d.loc[tr,'block_id'].nunique()),'test_blocks':int(d.loc[te,'block_id'].nunique()),'imputed_train_values':int((~np.isfinite(x[tr])).sum()),'imputed_test_values':int((~np.isfinite(x[te])).sum()),'rmse':float(np.sqrt(np.mean((pred[te]-y[te])**2)))})
    ck(f'all_OOF_finite_{ycol}_{size}_{model}',np.isfinite(pred).all());by_model[model]=pred;results.append({'outcome':ycol,'block_km':size,'model':model,'n':len(d),'n_blocks':d.block_id.nunique(),'features':cols,'RMSE_OOF':float(np.sqrt(np.mean((pred-y)**2))),'MAE_OOF':float(np.abs(pred-y).mean()),'R2_OOF':float(1-np.sum((pred-y)**2)/np.sum((y-y.mean())**2)),'folds':foldinfo});predictions.append(pd.DataFrame({'center_id':d.center_id,'outcome':ycol,'block_km':size,'model':model,'y':y,'prediction':pred,'fold':d.fold,'block_id':d.block_id}))
   for before,after in [('M1','M2'),('M2','M3'),('M1','M3')]:
    loss=pd.DataFrame({'block':d.block_id,'difference':(by_model[after]-y)**2-(by_model[before]-y)**2}).groupby('block').difference.agg(['sum','size']);boots=[]
    for _ in range(a.bootstrap_reps):ix=rng.integers(0,len(loss),len(loss));boots.append(loss['sum'].to_numpy()[ix].sum()/loss['size'].to_numpy()[ix].sum())
    lo,hi=np.quantile(boots,[.025,.975]);results.append({'outcome':ycol,'block_km':size,'comparison':after+' minus '+before,'delta_MSE':float(loss['sum'].sum()/loss['size'].sum()),'CI025':float(lo),'CI975':float(hi),'bootstrap_repetitions':a.bootstrap_reps,'meaning':'negative favors added predictors; paired whole-block bootstrap of fixed OOF errors, conditional on fitted folds, no model refit inside bootstrap'})
 f.to_parquet(o/'functional_same_cohort.parquet',index=False);pd.concat(predictions,ignore_index=True).to_csv(o/'functional_spatial_OOF_predictions.csv.gz',index=False,compression={'method':'gzip','mtime':0});summary={'status':'completed','primary_outcome':'log1p(total_population2021)-log1p(total_population2010)','secondary_outcome':'log1p(environment_population2021)-log1p(environment_population2010), structural noncenter_members>0 only','n_same_cohort':len(f),'zone_universe_nonresidual':int(geo.center_id.ne('UNASSIGNED').sum()),'zone_coverage':len(f)/geo.center_id.ne('UNASSIGNED').sum(),'population2010_coverage':float(f.population_2010.sum()/geo.population_2010.sum()),'selection':'crop coverage>=.8, observed organizations2021 baseline5km>=5, finite location; no demographic-value/source-metadata/outcome filtering','protocol':'fixed ridge penalty1,5 deterministic whole-spatial-block folds; train-only median imputation and scaling; main400km plus250/600 sensitivity; same rows/folds for all three models','seed':20261019,'interpretation':'2021 profiles are contemporaneous descriptive correlates of past2010–2021 dynamics, not prior causes or true forecasting; sectors are legal-address reporting economy, not jobs; crops are source-municipal profile composition, not allocated field hectares','limitations':'no gap buffer between adjacent train/test blocks; uncertainty conditional on fitted folds; coverage-selected results do not extrapolate to all zones','results':results,'input_checks':audit};(o/'functional_incremental_validation.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2));files=[r/'agriculture/zone_functional_main.csv',r/'rfsd/primary2010/financial_observations.parquet',r/'rfsd/primary2010/sector_sensitivity.parquet',o/'independent_zone_covariates.parquet'];(o/'functional_provenance.json').write_text(json.dumps([{'path':str(q.relative_to(r)),'sha256':hashlib.sha256(q.read_bytes()).hexdigest()} for q in files],indent=2));print(json.dumps(summary,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
